export function splitTags(values) {
    return [...new Set(values.flatMap(value => String(value).split(/[\s,，]+/))
        .map(tag => tag.trim().toLowerCase()).filter(Boolean))]
}

export function isValidTag(tag) {
    return /^[\w\u4e00-\u9fa5\u3040-\u309f\u30a0-\u30ff\uac00-\ud7af-]+$/.test(tag)
}

// Tags are always explicit. This supports compact expressions such as
// #travel#landscape -#draft -#watermark without treating normal words as tags.
export function parseTagSearch(query) {
    const quoted = []
    const withoutQuotes = String(query).replace(/"([^"]*)"/g, (_, text) => {
        quoted.push(text)
        return ` \u0000${quoted.length - 1}\u0000 `
    })
    const includeTags = [], excludeTags = []
    let hasTag = false
    const keywords = withoutQuotes
        .replace(/(-?)#([\w\u4e00-\u9fa5\u3040-\u309f\u30a0-\u30ff\uac00-\ud7af-]+)/g, (_, excluded, tag) => {
            hasTag = true;
            (excluded ? excludeTags : includeTags).push(tag.toLowerCase())
            return ' '
        })
        .replace(/\u0000(\d+)\u0000/g, (_, index) => quoted[Number(index)])
        .replace(hasTag ? /[\s,，]+/g : /\s+/g, ' ')
        .trim()
    return {
        keywords,
        includeTags: [...new Set(includeTags)],
        excludeTags: [...new Set(excludeTags)]
    }
}
